const char* label_id = is_job_label ? _dcss_job_label_id(static_cast<job_type>(id))
    : _dcss_species_label_id(static_cast<species_type>(id));
const char* domain = is_job_label ? "job" : "species";
const string params = "{" + _dcss_json_string(domain) + ":" + _dcss_entity_label(domain, label_id) + "}";
text += _dcss_startup_dynamic_text(is_job_label ? "startup.dynamic.job_name" : "startup.dynamic.species_name", params, item_name);
