const bool canonical_an = is_vowel(specs[0]);
const string canonical_title = make_stringf("You are a%s %s %s.",
        canonical_an ? "n" : "", specs.c_str(), get_job_name(ng.job));
title.cprintf("%s", _dcss_startup_dynamic_text(canonical_an ? "startup.dynamic.character.an" : "startup.dynamic.character.a",
        _dcss_character_params(ng.species, ng.job), canonical_title).c_str());

text = "Welcome" + text + ".";
const bool named = !ng.name.empty();
const bool species_known = ng.species != SP_UNKNOWN;
const bool job_known = ng.job != JOB_UNKNOWN;
const char* id = named ? (species_known ? (job_known ? "startup.dynamic.welcome.named_species_job" : "startup.dynamic.welcome.named_species")
    : (job_known ? "startup.dynamic.welcome.named_job" : "startup.dynamic.welcome.named_only"))
    : (species_known ? (job_known ? "startup.dynamic.welcome.unnamed_species_job" : "startup.dynamic.welcome.unnamed_species")
    : (job_known ? "startup.dynamic.welcome.unnamed_job" : "startup.dynamic.welcome.empty"));
string params = "{";
if (species_known)
    params += "\"species\":" + _dcss_entity_label("species", _dcss_species_label_id(ng.species));
if (job_known)
{
    if (params.size() > 1) params += ",";
    params += "\"job\":" + _dcss_entity_label("job", _dcss_job_label_id(ng.job));
}
if (named)
{
    if (params.size() > 1) params += ",";
    params += "\"player_name\":" + _dcss_external_actor_label(ng.name);
}
params += "}";
return _dcss_startup_dynamic_text(id, params, text);
